window.HOEREN_TESTS[58] = {"id":"beim-friseur-maenner","name":"Beim Friseur Männer","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Der Barbier-Salon Klassik öffnet ab Donnerstag. Nicht Montag und nicht Samstag, wirklich erst ab Donnerstag. Spezialist für Männer-Haarschnitt, Bart-Pflege, klassisches Rasieren. Eröffnungsangebot: 30% Rabatt erste zwei Wochen. Termin online oder telefonisch. Wir freuen uns auf erste Männer-Kunden! Kommen Sie vorbei, wir beraten gern!","gender":"m","q":"Wann öffnet der Salon?","opts":["Montag.","Donnerstag.","Samstag."],"correct":1},{"transcript":"Hallo Markus, hier ist Tom. Hey, mein Bart wird zu lang. Habe Termin morgen beim Barbier, 14 Uhr. Abrasieren will ich ihn nicht, und wachsen lassen auch nicht, nur pflegen lassen. Möchtest du mitkommen? Du hast auch einen ungepflegten Bart, sage ich ehrlich. Treffen wir uns davor zum Mittagessen. Ruf zurück, bis bald!","gender":"m","q":"Was möchte Tom?","opts":["Bart pflegen lassen.","Bart abrasieren.","Bart wachsen lassen."],"correct":0},{"transcript":"Achtung Kunden: Klassische Rasur mit Messer ist nur noch bei vorheriger Anmeldung. Spontan geht nicht — dauert 30 Minuten pro Person, brauchen wir Zeit. Bitte zwei Tage vorher anrufen. Normale Bart-Pflege auch spontan möglich. Haarschnitt geht immer spontan, nur die Rasur nicht. Vielen Dank für Verständnis!","gender":"f","q":"Was braucht Anmeldung?","opts":["Normale Bart-Pflege.","Haarschnitt.","Klassische Rasur mit Messer."],"correct":2},{"transcript":"Hi Anna, hier ist Lisa. Du, mein Mann hat einen schlechten Haarschnitt bekommen — viel zu kurz! Nicht falsche Farbe und nicht falscher Stil, einfach viel zu kurz. Sieht aus wie ein Soldat. Er ist sauer auf den Friseur. Wechselt jetzt zum Barbier in der Hauptstraße — kennst du den? Soll besser sein. Was meinst du?","gender":"f","q":"Was ist passiert?","opts":["Falsche Farbe.","Haare zu kurz geschnitten.","Falscher Stil."],"correct":1},{"transcript":"Liebe Kunden: Wir bieten ab Mai ein Bart-Komplett-Paket — Rasur, Pflege-Öl, Form-Modellierung. Alles zusammen 35 Euro statt 50 wenn einzeln. 25 Euro kostet nur die kleine Pflege ohne Rasur. Auch Bart-Beratung kostenlos: welche Form passt zu welchem Gesicht? Termin nötig. Wir freuen uns! Fragen Sie uns, wir helfen gern!","gender":"m","q":"Was kostet das Komplett-Paket?","opts":["35 Euro.","50 Euro.","25 Euro."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer hat welche Frisur? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lars! Der Friseur hat um vier noch einen Stuhl frei."},{"speaker":"Lars","gender":"m","text":"Das freut mich. Ich will vor dem Fest endlich anders aussehen."},{"speaker":"Lukas","gender":"m","text":"Ich nehme die Glatze. Im Sommer bleibt der Kopf dann angenehm kühl."},{"speaker":"Lars","gender":"m","text":"Ich will einen Iro als Mohawk. In der Mitte bleibt nur ein schmaler Streifen."},{"speaker":"Lukas","gender":"m","text":"Will jemand einen langen Pferdeschwanz?"},{"speaker":"Lars","gender":"m","text":"Nein. Einen Pferdeschwanz will hier keiner."},{"speaker":"Lukas","gender":"m","text":"Tom kommt nach einem ganzen Jahr zum ersten Schnitt."},{"speaker":"Lars","gender":"m","text":"Tom trägt einen Mittelscheitel mit langen Haaren. Sie fallen ihm weit über den Rücken."},{"speaker":"Lukas","gender":"m","text":"Sven bindet morgens alles nach oben zusammen und spart so Zeit."},{"speaker":"Lars","gender":"m","text":"Sven trägt einen Dutt. Oben auf dem Kopf wirkt das ordentlich."},{"speaker":"Lukas","gender":"m","text":"Will jemand Dreadlocks bis auf die Schulter?"},{"speaker":"Lars","gender":"m","text":"Nein. Dreadlocks wollen wir nicht. Die Pflege dauert uns zu lang."},{"speaker":"Lukas","gender":"m","text":"Tim will die Seiten kurz und oben deutlich länger."},{"speaker":"Lars","gender":"m","text":"Tim nimmt einen Undercut. Die Seiten werden dann ganz kurz geschnitten."},{"speaker":"Lukas","gender":"m","text":"Dann setzen wir uns um vier zusammen auf die Stühle."},{"speaker":"Lars","gender":"m","text":"Ich bringe ein Foto von der Wunschfrisur mit."}],"options":[{"letter":"a","text":"Pferdeschwanz"},{"letter":"b","text":"Iro / Mohawk"},{"letter":"c","text":"Dutt"},{"letter":"d","text":"Mittelscheitel mit langen Haaren"},{"letter":"e","text":"Dreadlocks"},{"letter":"f","text":"Locken"},{"letter":"g","text":"Bürstenschnitt"},{"letter":"h","text":"Glatze"},{"letter":"i","text":"Undercut"}],"items":[{"person":"Lukas","correct":"h"},{"person":"Lars","correct":"b"},{"person":"Tom","correct":"d"},{"person":"Sven","correct":"c"},{"person":"Tim","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag! Wie lange dauert es? Ich habe Eile."},{"speaker":"Barbier","gender":"m","text":"Haarschnitt 25 Minuten, mit Bart 40 Minuten. Eine Stunde brauchen wir nie, garantiert."},{"speaker":"Kunde","gender":"m","text":"Dann nur Haare, bitte, ohne Bart."},{"speaker":"Barbier","gender":"m","text":"Alles klar, 25 Minuten. Nehmen Sie bitte Platz."},{"speaker":"Kunde","gender":"m","text":"Perfekt! In 25 Minuten bin ich wieder weg. Danke! Vielen Dank!"},{"speaker":"Barbier","gender":"m","text":"So, fertig! Sehen Sie gut aus, bis zum nächsten Mal!"}],"q":"Wie lange dauert es?","opts":["40 Minuten.","25 Minuten.","Eine Stunde."],"correct":1},{"lines":[{"speaker":"Junge","gender":"m","text":"Mama, ich will nicht zum Friseur! Bitte nicht!"},{"speaker":"Mutter","gender":"f","text":"Aber Schulanfang ist bald! Du musst ordentlich aussehen, nächste Woche!"},{"speaker":"Junge","gender":"m","text":"Okay, aber nicht sehr kurz, bitte! Und färben auch nicht!"},{"speaker":"Mutter","gender":"f","text":"Versprochen, nicht kurz und kein Färben. Nur Spitzen schneiden."},{"speaker":"Junge","gender":"m","text":"Nur Spitzen? Na gut, einverstanden. Aber schnell! Mama!"}],"q":"Was wird gemacht?","opts":["Nur Spitzen.","Sehr kurz.","Färben."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Ich werde grau, überall! Was soll ich tun? Färben oder akzeptieren, wirklich?"},{"speaker":"Friseur","gender":"m","text":"Viele färben. Schwarz oder blond? Oder dunkelbraun?"},{"speaker":"Mann","gender":"m","text":"Schwarz ist zu hart, blond passt nicht zu mir."},{"speaker":"Friseur","gender":"m","text":"Dann dunkelbraun, das sieht am natürlichsten aus."},{"speaker":"Mann","gender":"m","text":"Gut, dunkelbraun! Wann haben Sie Zeit? Morgen vielleicht am Abend?"}],"q":"Welche Farbe?","opts":["Schwarz.","Blond.","Dunkelbraun."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag! Wann ist mein Termin? Freitag um 17 Uhr?"},{"speaker":"Empfangs-Dame","gender":"f","text":"Ja, Freitag 17 Uhr steht hier. Möchten Sie im Buch wechseln?"},{"speaker":"Kunde","gender":"m","text":"Geht auch Samstag? Da habe ich Zeit."},{"speaker":"Empfangs-Dame","gender":"f","text":"Samstag ist leider voll. Donnerstag wäre möglich."},{"speaker":"Kunde","gender":"m","text":"Gut, dann Donnerstag! Gleiche Uhrzeit wie Freitag?"},{"speaker":"Empfangs-Dame","gender":"f","text":"Ja, Donnerstag 17 Uhr. Bis dann! Tschüss!"}],"q":"Welcher Tag?","opts":["Donnerstag.","Freitag.","Samstag."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Sohn, dein Bart muss weg vor dem Vorstellungsgespräch!"},{"speaker":"Sohn","gender":"m","text":"Aber Papa, Bart ist Trend! Nur trimmen reicht doch auch."},{"speaker":"Vater","gender":"m","text":"Trimmen reicht nicht. Das macht schlechten Eindruck beim Chef."},{"speaker":"Sohn","gender":"m","text":"Und behalten geht gar nicht? Wirklich nicht?"},{"speaker":"Vater","gender":"m","text":"Nein, also: Rasieren, bitte, noch heute!"},{"speaker":"Sohn","gender":"m","text":"Okay, okay, ich rasiere. Aber danach lasse ich ihn wieder wachsen!"}],"q":"Was macht der Sohn?","opts":["Bart behalten.","Bart rasieren.","Bart trimmen."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Schmidt, einem Barbier-Meister. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Schmidt, Sie haben Ihren Barbier-Salon seit 10 Jahren. Wie hat sich Männer-Pflege geändert?"},{"speaker":"Schmidt","gender":"m","text":"Sehr stark! Vor 10 Jahren war Männer-Pflege ein Tabu — Mann ging zum Friseur, das war's. Heute kommen Männer regelmäßig für Bart-Pflege, Haarkur, sogar Maniküre. Mode hat sich gewandelt — Männer kümmern sich endlich um sich."},{"speaker":"Reporterin","gender":"f","text":"Welche Trends sehen Sie heute?"},{"speaker":"Schmidt","gender":"m","text":"Bärte definitiv — alle Formen, von Vollbart bis Drei-Tage-Stoppeln. Undercut bei Haarschnitt sehr beliebt. Auch klassische Rasur mit Messer kommt zurück — alte Tradition, neue Generation interessiert sich. Schöner Trend."},{"speaker":"Reporterin","gender":"f","text":"Wer sind Ihre Kunden?"},{"speaker":"Schmidt","gender":"m","text":"Alle Altersklassen. Junge Männer — Trend-bewusst, kommen jede zweite Woche. Ältere Herren — Stamm-Kunden, schon Jahre dabei. Sogar Teenager kommen mit ihren Vätern. Männer-Friseur ist heute Familie-Tradition."},{"speaker":"Reporterin","gender":"f","text":"Was sind häufige Wünsche?"},{"speaker":"Schmidt","gender":"m","text":"Bart-Form individualisieren — passend zu Gesicht und Beruf. Manche Berufe — Bank, Recht — wollen klassisch. Andere — IT, Kreativ — wagen mehr. Auch grauen Bart färben — wird häufiger gefragt. Männer wollen jünger aussehen."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie Männern?"},{"speaker":"Schmidt","gender":"m","text":"Bart selbst pflegen zwischen Terminen — gutes Öl, Kämmen. Haare alle 6 Wochen schneiden lassen — länger nicht warten. Und Beratung nehmen — was zum Gesicht passt, weiß Barbier besser als ihr selbst. Vertrauen lohnt sich."}],"items":[{"q":"Männer kümmerten sich vor 10 Jahren weniger um Pflege.","correct":"ja"},{"q":"Klassische Rasur mit Messer ist heute völlig verschwunden.","correct":"nein"},{"q":"Auch Teenager kommen mit ihren Vätern zum Barbier.","correct":"ja"},{"q":"Bart färben wird häufiger gefragt.","correct":"ja"},{"q":"Er rät, alle 12 Wochen zum Haarschnitt zu kommen.","correct":"nein"}]}]};
